HolyStorm:ApplyModuleMetadata(Logs,{displayName=L["TITLE"],internalName="logs",version=addonVersion,category="required",description=L["DESCRIPTION"],permissions={"logs-view"},dependencies={"core","ui"},enabledByDefault=true})

local FILTER_KEYS={level=true,module=true,category=true,direction=true,event=true,search=true}
local SEARCH_CONTEXT={"from","to","domain","objectId","messageKind","transmissionId","event","eventName"}
local EXPORT_CONTEXT={"direction","from","to","channel","domain","objectId","transmissionId","packetPart","packetTotal","bytes","messageKind","version","reason","requestId","event","eventName","taskId","workflowId","triggerSource"}
local LEVEL_COLORS={DEBUG={.58,.68,.78},INFO={.82,.92,1},WARN={1,.72,.2},ERROR={1,.28,.28}}
local CATEGORY_COLORS={event={.45,.78,1},task={.66,.74,.86},workflow={.75,.58,1},sync={.35,.82,.86},payload={.35,.88,.64},send={.38,.82,1},receive={.5,.9,.72},comms={.45,.8,1},database={.82,.68,.4},permission={1,.72,.3},ui={.82,.65,1}}
local OMIT_CONTEXT={payload=true,data=true,database=true,equipment=true,serialized=true,message=true,packet=true,envelope=true}

local function lower(value)return string.lower(tostring(value or""))end
local function context(entry)return type(entry.context)=="table"and entry.context or{}end
local function field(entry,name)local c=context(entry);if name=="direction"then return entry.direction or c.direction elseif name=="event"then return entry.eventName or c.eventName or c.event end;return c[name]end
local function direction(entry)return string.upper(tostring(field(entry,"direction")or""))end
local function eventName(entry)return tostring(field(entry,"event")or"")end
local function transmission(entry)return tostring(entry.transmissionId or field(entry,"transmissionId")or"")end
local function correlation(entry)return tostring(entry.correlationId or field(entry,"correlationId")or"")end
local DESTINATION_KEYS={GUILD=true,RAID=true,PARTY=true,INSTANCE=true,BROADCAST=true}
local function destination(value)local key=string.upper(tostring(value or""));return DESTINATION_KEYS[key]and L[key]or value end
local function route(entry)local c=context(entry);local from=c.from;local to=destination(c.to);if from and to then return tostring(from).." → "..tostring(to)end;return tostring(from or to or"")end
local function progress(entry)local c=context(entry);local part,total=tonumber(c.packetPart),tonumber(c.packetTotal);return part and total and string.format("%d / %d",part,total)or""end
local function safeContext(source)local out={};source=type(source)=="table"and source or{};for _,key in ipairs(EXPORT_CONTEXT)do local value=source[key];if type(value)=="string"or type(value)=="number"or type(value)=="boolean"then out[key]=value end end;return out end
local function flattenContext(source,prefix,out,depth)out=out or{};depth=depth or 0;if type(source)~="table"or depth>3 or#out>=100 then return out end;local keys={};for key in pairs(source)do if type(key)=="string"and not OMIT_CONTEXT[key]then keys[#keys+1]=key end end;table.sort(keys);for _,key in ipairs(keys)do if#out>=100 then break end;local value=source[key];local path=prefix and(prefix.."."..key)or key;if type(value)=="string"or type(value)=="number"or type(value)=="boolean"then out[#out+1]={path,tostring(value)}elseif type(value)=="table"then flattenContext(value,path,out,depth+1)end end;return out end
local function exportEntry(entry)local c=safeContext(context(entry));return{timestamp=tonumber(entry.timestamp),level=tostring(entry.level or""),source=tostring(entry.source or""),category=tostring(entry.category or""),message=tostring(entry.message or""),direction=direction(entry),from=c.from,to=c.to,channel=c.channel,domain=c.domain,objectId=c.objectId,transmissionId=transmission(entry),packetPart=c.packetPart,packetTotal=c.packetTotal,bytes=c.bytes,messageKind=c.messageKind,version=c.version,eventName=eventName(entry),correlationId=correlation(entry),context=c}end
local function json(value)
 if value==nil then return"null"elseif type(value)=="boolean"or type(value)=="number"then return tostring(value)elseif type(value)=="string"then return'"'..value:gsub('\\','\\\\'):gsub('"','\\"'):gsub('\n','\\n'):gsub('\r','\\r')..'"'elseif type(value)~="table"then return"null"end
 local array,count=true,0;for key in pairs(value)do count=count+1;if type(key)~="number"then array=false end end;local out={};if array then for index=1,count do out[#out+1]=json(value[index])end;return"["..table.concat(out,",").."]"end;for key,child in pairs(value)do out[#out+1]=json(tostring(key))..":"..json(child)end;table.sort(out);return"{"..table.concat(out,",").."}"
end
local function csv(value)return'"'..tostring(value or""):gsub('"','""')..'"'end

function Logs:GetSettings()
 HolyStorm.db.profile.logs=type(HolyStorm.db.profile.logs)=="table"and HolyStorm.db.profile.logs or{};local settings=HolyStorm.db.profile.logs;settings.autoScroll=settings.autoScroll~=false;for key in pairs(FILTER_KEYS)do if key~="search"and type(settings[key])~="string"then settings[key]="ALL"end end;settings.search=type(settings.search)=="string"and settings.search or"";return settings
end
function Logs:LoadSettings()local settings=self:GetSettings();self.filters={level=settings.level or"ALL",module=settings.module or"ALL",category=settings.category or"ALL",direction=settings.direction or"ALL",event=settings.event or"ALL",search=settings.search or""};self.autoScroll=settings.autoScroll~=false;return self.filters end
function Logs:SetFilter(name,value,skipRender)if not FILTER_KEYS[name]then return false end;self.filters=self.filters or self:LoadSettings();value=name=="search"and tostring(value or"")or tostring(value or"ALL");self.filters[name]=value;self:GetSettings()[name]=value;if self.filterMenus and self.filterMenus[name]then self:UpdateMenuText(name)end;if not skipRender then self:Render()end;return true end
function Logs:ResetFilters(skipRender)self.filters=self.filters or{};for key in pairs(FILTER_KEYS)do self:SetFilter(key,key=="search"and""or"ALL",true)end;if self.searchBox then self.searchBox:SetText("")end;if not skipRender then self:Render()end end
function Logs:SetQuickFilter(kind)self:ResetFilters(true);if kind=="ERROR"or kind=="WARN"then self:SetFilter("level",kind,true)elseif kind=="EVENT"or kind=="TASK"or kind=="WORKFLOW"then self:SetFilter("category",string.lower(kind),true)elseif kind=="SYNC"or kind=="COMMS"then self:SetFilter("module",kind=="SYNC"and"Sync"or"Comms",true)end;self:Render()end
function Logs:GetOptions(kind)local seen,out={},{};for _,entry in ipairs(HolyStorm.Logger:GetHistory())do local value;if kind=="level"then value=entry.level elseif kind=="module"then value=entry.source elseif kind=="category"then value=entry.category elseif kind=="direction"then value=direction(entry)elseif kind=="event"then value=eventName(entry)end;if value and value~=""and not seen[value]then seen[value]=true;out[#out+1]=value end end;table.sort(out,function(a,b)return lower(a)<lower(b)end);return out end
function Logs:EnsureValidFilters()self.filters=self.filters or self:LoadSettings();for _,kind in ipairs({"level","module","category","direction","event"})do local selected=self.filters[kind];if selected and selected~="ALL"then local found=false;for _,value in ipairs(self:GetOptions(kind))do if lower(value)==lower(selected)then found=true;break end end;if not found then self:SetFilter(kind,"ALL",true)end end end end
function Logs:Matches(entry)
 local filters=self.filters or self:LoadSettings();if filters.level~="ALL"and lower(entry.level)~=lower(filters.level)then return false end;if filters.module~="ALL"and lower(entry.source)~=lower(filters.module)then return false end;if filters.category~="ALL"and lower(entry.category)~=lower(filters.category)then return false end;if filters.direction~="ALL"and lower(direction(entry))~=lower(filters.direction)then return false end;if filters.event~="ALL"and lower(eventName(entry))~=lower(filters.event)then return false end
 local query=lower(filters.search);if query~=""then local values={entry.message,entry.source,entry.category,entry.correlationId,entry.transmissionId};local c=context(entry);for _,name in ipairs(SEARCH_CONTEXT)do values[#values+1]=c[name]end;local found=false;for _,value in ipairs(values)do if lower(value):find(query,1,true)then found=true;break end end;if not found then return false end end;return true
end
function Logs:GetFiltered()local out={};for _,entry in ipairs(HolyStorm.Logger:GetHistory())do if self:Matches(entry)then out[#out+1]=entry end end;return out end

function Logs:Export(format,all)
 local entries=all and HolyStorm.Logger:GetHistory()or self:GetFiltered();local projected={};for _,entry in ipairs(entries)do projected[#projected+1]=exportEntry(entry)end;if format=="json"then return json(projected)end
 local lines={};if format=="csv"then lines[1]="timestamp,level,module,category,direction,from,to,channel,domain,objectId,transmissionId,packetPart,packetTotal,bytes,messageKind,version,eventName,correlationId,message";for _,entry in ipairs(projected)do lines[#lines+1]=table.concat({csv(entry.timestamp),csv(entry.level),csv(entry.source),csv(entry.category),csv(entry.direction),csv(entry.from),csv(entry.to),csv(entry.channel),csv(entry.domain),csv(entry.objectId),csv(entry.transmissionId),csv(entry.packetPart),csv(entry.packetTotal),csv(entry.bytes),csv(entry.messageKind),csv(entry.version),csv(entry.eventName),csv(entry.correlationId),csv(entry.message)},",")end else for _,entry in ipairs(projected)do local extra=route(entry);local packet=entry.packetPart and entry.packetTotal and string.format(" %s/%s",entry.packetPart,entry.packetTotal)or"";lines[#lines+1]=string.format("%s [%s] [%s/%s] %s%s%s%s",date("%Y-%m-%d %H:%M:%S",entry.timestamp),entry.level,entry.source,entry.category,entry.direction~=""and(entry.direction.." ")or"",extra,packet,entry.message~=""and(" | "..entry.message)or"")end end;return table.concat(lines,"\n")
end
function Logs:ExportDiscord(all)local entries=all and HolyStorm.Logger:GetHistory()or self:GetFiltered();local modules={};for _,entry in ipairs(entries)do modules[entry.source or"-"]=true end;local names={};for name in pairs(modules)do names[#names+1]=name end;table.sort(names);return string.format("**"..L["LOG_EXPORT_TITLE"].."**\n%s: %s\n%s: %s\n%s: %s / %s\n```text\n%s\n```",HolyStorm.version,L["LOG_EXPORT_TIME"],date("%Y-%m-%d %H:%M:%S"),L["LOG_EXPORT_MODULES"],table.concat(names,", "),L["LOG_EXPORT_FILTER"],all and L["ALL"]or self.filters.level,all and""or self.filters.search,self:Export("text",all))end

