function Logs:FormatDetails(entry)
 if not entry then return L["NO_LOG_ENTRIES"]end;local c=context(entry);local lines={L["TIME"]..": "..date("%Y-%m-%d %H:%M:%S",tonumber(entry.timestamp)or 0),L["LEVEL"]..": "..tostring(entry.level or"-"),L["MODULE"]..": "..tostring(entry.source or"-"),L["CATEGORY"]..": "..tostring(entry.category or"-"),L["MESSAGE"]..": "..tostring(entry.message or"-")};local labels={direction=L["DIRECTION"],from=L["FROM"],to=L["TO"],channel=L["CHANNEL"],domain=L["DOMAIN"],objectId=L["OBJECT"],transmissionId=L["TRANSMISSION"],correlationId=L["CORRELATION_ID"]};for _,key in ipairs({"direction","from","to","channel","domain","objectId","transmissionId","correlationId"})do local value=key=="transmissionId"and transmission(entry)or key=="correlationId"and correlation(entry)or c[key];if value and value~=""then lines[#lines+1]=labels[key]..": "..tostring(destination(value))end end;if c.packetPart or c.packetTotal then lines[#lines+1]=L["PACKET"]..": "..tostring(c.packetPart or"-").." / "..tostring(c.packetTotal or"-")end
