local columnDefinitions={{id="time",label="TIME",width=.075},{id="level",label="LEVEL",width=.07},{id="module",label="MODULE",width=.105},{id="category",label="CATEGORY",width=.10},{id="direction",label="DIRECTION",width=.075},{id="route",label="ROUTE",width=.18},{id="progress",label="PROGRESS",width=.075},{id="correlation",label="CORRELATION_ID",width=.12},{id="message",label="MESSAGE",width=.20}}
